-- 144: Original BrillaPrep WASSCE BrillaPrep transitional Auto Mechanics beta content blueprint questions, part 2.
-- Curriculum-aligned practice content; not official WAEC examination material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_144_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_144_guard;
INSERT INTO _migration_144_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_auto_mech_b002_006' AND NOT (q.topic_id IS 'topic_was_auto_mech_b002_2' AND q.subject_id IS 'subj_wassce_auto_mech' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'During which four-stroke engine stroke are both valves normally closed while the piston moves upward?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. The exhaust stroke","B. The compression stroke","C. The induction stroke","D. The power stroke"]' AND q.correct_answer IS 'B' AND q.explanation IS 'On the compression stroke the trapped charge is compressed as the piston rises, requiring the inlet and exhaust valves to remain closed. Therefore the correct answer is B: The compression stroke.' AND q.difficulty IS 'hard' AND q.points IS '2' AND q.marks IS '2' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_auto_mech_b002_2' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO3' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_auto_mech_b002_006' AND NOT (r.batch_id IS 'wassce-technical-beta-002' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Auto Mechanics practice aligned to WAEC Ghana examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_144_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_auto_mech_b002_007' AND NOT (q.topic_id IS 'topic_was_auto_mech_b002_2' AND q.subject_id IS 'subj_wassce_auto_mech' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'What is the main function of piston rings in a reciprocating engine?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Locate the piston at top dead centre","B. Transfer camshaft motion to the valves","C. Seal combustion pressure while controlling oil on the cylinder wall","D. Control coolant flow through the cylinder head"]' AND q.correct_answer IS 'C' AND q.explanation IS 'Compression rings limit gas leakage and the oil-control ring regulates the oil film, supporting compression, lubrication and heat transfer. Therefore the correct answer is C: Seal combustion pressure while controlling oil on the cylinder wall.' AND q.difficulty IS 'easy' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_auto_mech_b002_2' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_auto_mech_b002_007' AND NOT (r.batch_id IS 'wassce-technical-beta-002' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Auto Mechanics practice aligned to WAEC Ghana examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_144_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_auto_mech_b002_008' AND NOT (q.topic_id IS 'topic_was_auto_mech_b002_2' AND q.subject_id IS 'subj_wassce_auto_mech' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Which component converts the pistons’ reciprocating motion into rotary motion?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. The camshaft","B. The flywheel","C. The connecting rod","D. The crankshaft"]' AND q.correct_answer IS 'D' AND q.explanation IS 'Connecting rods transmit piston force to offset crankpins, causing the crankshaft to rotate and deliver engine torque. Therefore the correct answer is D: The crankshaft.' AND q.difficulty IS 'medium' AND q.points IS '2' AND q.marks IS '2' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_auto_mech_b002_2' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_auto_mech_b002_008' AND NOT (r.batch_id IS 'wassce-technical-beta-002' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Auto Mechanics practice aligned to WAEC Ghana examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_144_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_auto_mech_b002_009' AND NOT (q.topic_id IS 'topic_was_auto_mech_b002_2' AND q.subject_id IS 'subj_wassce_auto_mech' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'What does engine compression ratio compare?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Cylinder volume at bottom dead centre with volume at top dead centre","B. Swept volume with total engine displacement","C. Combustion pressure before and after ignition","D. Cylinder bore with piston stroke"]' AND q.correct_answer IS 'A' AND q.explanation IS 'Compression ratio is the maximum cylinder volume divided by the minimum clearance volume and influences efficiency and combustion requirements. Therefore the correct answer is A: Cylinder volume at bottom dead centre with volume at top dead centre.' AND q.difficulty IS 'hard' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_auto_mech_b002_2' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO3' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_auto_mech_b002_009' AND NOT (r.batch_id IS 'wassce-technical-beta-002' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Auto Mechanics practice aligned to WAEC Ghana examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_144_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_auto_mech_b002_010' AND NOT (q.topic_id IS 'topic_was_auto_mech_b002_2' AND q.subject_id IS 'subj_wassce_auto_mech' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Why is valve clearance provided in a conventional valve train?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. To increase valve lift as speed rises","B. To allow thermal expansion while ensuring the valves can fully close","C. To hold each valve slightly open during compression","D. To compensate for piston-ring wear"]' AND q.correct_answer IS 'B' AND q.explanation IS 'A correct cold clearance accommodates expansion of valve-train parts; too little can prevent sealing and too much causes noise and timing loss. Therefore the correct answer is B: To allow thermal expansion while ensuring the valves can fully close.' AND q.difficulty IS 'easy' AND q.points IS '3' AND q.marks IS '3' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_auto_mech_b002_2' AND q.command_word IS 'Explain' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_auto_mech_b002_010' AND NOT (r.batch_id IS 'wassce-technical-beta-002' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Auto Mechanics practice aligned to WAEC Ghana examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
